 const selectedRows=holdingRows.filter(x=>currentSymbols.includes(x.h.symbol)); const currentSnapshotValue=selectedRows.reduce((a,x)=>a+x.hm.marketValue,0); const currentTradeCost=selectedRows.reduce((a,x)=>a+x.hm.pureCost,0); const currentCashBasis=selectedRows.reduce((a,x)=>a+x.hm.totalCost,0); const currentDividends=selectedRows.reduce((a,x)=>a+x.hm.cumulativeDividend,0);
