 const pm=portfolioMetrics(common.holdings,common.quotes,common.cashBalance,common.ledger,common.dividends); const effectiveInitial=sourceMode==='current'?currentSnapshotValue:Number(initial||0); const sim=simulateMonthly(effectiveInitial,Number(monthly||0),Number(years||0),Number(rate||0),Number(divYield||0),reinvest);
 const calc:any={sourceMode:sourceMode==='current'?'目前持有庫存自訂組合':'自由建立新組合',initialCapital:money(effectiveInitial),currentSnapshotValue:money(currentSnapshotValue),monthlyContribution:money(Number(monthly||0)),years:`${Number(years||0)} 年`,annualReturn:`${Number(rate||0).toFixed(2)}%`,annualDividendYield:`${Number(divYield||0).toFixed(2)}%`,invested:money(sim.invested),futureValue:money(sim.value),cumulativeDividend:money(sim.cumulativeDividend),pnl:money(sim.pnl),roi:pct(sim.roi)};
 const targetCapital=Number(retireYield)>0?Number(retireIncome||0)*12/(Number(retireYield)/100):0; const months=Math.max(1,Number(years||0)*12); const mr=Math.pow(1+Number(rate||0)/100,1/12)-1; const futureInitial=effectiveInitial*Math.pow(1+mr,months); const needed=Math.max(0,targetCapital-futureInitial); const requiredMonthly=mr>0?needed*mr/(Math.pow(1+mr,months)-1):needed/months;
 const allocations=sourceMode==='current'?selectedRows.map(x=>({symbol:x.h.symbol,name:x.h.name,weight:Math.max(0,Number(currentWeights[x.h.symbol]??0))/100})):customAllocations.map(x=>({symbol:x.symbol,name:x.name,weight:Math.max(0,x.weight)/100})); const allocationWeightTotal=allocations.reduce((a,x)=>a+x.weight,0); const calcMatches=customQuery.trim()?searchEtfCatalog(calcCatalog,customQuery,6):[];
