export type MarketMeta={lastSuccessAt?:number;lastAttemptAt?:number;error?:string;marketOpen:boolean;source:string;controllerStatus?:'live'|'afterHours'|'paused'|'holiday'|'offline'|'stopped'|'immediate'|'error';controllerSeconds?:number};

function marketStatusLabel(status:MarketMeta['controllerStatus'],error?:string){
 if(status==='live')return '🟢 即時更新中';
 if(status==='afterHours')return '🔵 盤後更新中';
 if(status==='paused')return '🟡 時段外暫停';
 if(status==='holiday')return '⚪ 休市';
 if(status==='stopped')return '⛔ 已停止更新';
 if(status==='immediate')return '🔄 立即更新中';
 if(status==='error')return `⚠️ 更新失敗${error?`：${error}`:''}`;
 if(status==='offline')return '🔴 離線';
 return '🟡 時段外暫停';
}
type ThemeEditDraft=Pick<V3Preferences,'backgroundPreset'|'backgroundImageUri'|'backgroundOpacity'|'overlayOpacity'|'cardOpacity'|'cardRadius'|'cardBackgroundImageUri'|'cardBackgroundImageOpacity'|'fontScale'|'primaryTextColor'|'secondaryTextColor'|'accentColor'|'positiveColor'|'negativeColor'|'navDisplayMode'|'iconDisplay'>;
