function MonitorLivePreview({profile,ordered,labels,values,prefs}:{profile:MonitorProfile;ordered:MonitorField[];labels:Record<string,string>;values:Record<string,string>;prefs:V3Preferences}){const origin=useRef({x:0,y:0});const pos=useRef(new Animated.ValueXY({x:0,y:0})).current;const pan=useMemo(()=>PanResponder.create({onStartShouldSetPanResponder:()=>true,onMoveShouldSetPanResponder:(_e,g)=>Math.abs(g.dx)>2||Math.abs(g.dy)>2,onPanResponderMove:(_e,g)=>pos.setValue({x:origin.current.x+g.dx,y:origin.current.y+g.dy}),onPanResponderRelease:(_e,g)=>{origin.current={x:origin.current.x+g.dx,y:origin.current.y+g.dy};pos.setValue(origin.current)}}),[pos]);const scale=Math.min(1,300/Math.max(120,profile.width),205/Math.max(80,profile.height));const visible=ordered.filter(k=>profile.fieldStyles?.[k]?.visible!==false).slice(0,7);return <View style={{height:245,borderWidth:1,borderColor:'rgba(255,255,255,.08)',borderRadius:12,backgroundColor:'rgba(0,0,0,.16)',overflow:'hidden',marginTop:8}}><Animated.View {...pan.panHandlers} style={{position:'absolute',left:10,top:10,width:profile.width*scale,height:profile.height*scale,minWidth:120,minHeight:78,padding:8,borderRadius:Math.max(4,profile.radius*scale),borderWidth:Math.max(1,profile.borderWidth),borderColor:profile.borderColor,backgroundColor:profile.backgroundColor,opacity:Math.max(.25,profile.activeOpacity/100),transform:pos.getTranslateTransform(),elevation:8}}><Text style={{color:prefs.accentColor,fontWeight:'900',fontSize:Math.max(8,11*profile.fontScale/100)}} numberOfLines={1}>☰ {profile.title}　{profile.locked?'🔒':'🔓'}</Text><Text style={{color:prefs.secondaryTextColor,fontSize:8,marginTop:2}}>{profile.width} × {profile.height}px · 真實資料預覽</Text><View style={{marginTop:5,gap:2}}>{visible.map(k=>{const st=profile.fieldStyles?.[k];const pnl=['premium','change','changePct','instantPnl','instantRoi','todayPnl','todayPnlPct'].includes(k);const raw=Number(String(values[k]??'').replace(/[^0-9.+-]/g,''));const color=st?.profitLossColor&&pnl&&Number.isFinite(raw)?raw>0?(st.positiveColor||prefs.positiveColor):raw<0?(st.negativeColor||prefs.negativeColor):(st.neutralColor||prefs.secondaryTextColor):(st?.textColor||prefs.primaryTextColor);return <View key={k} style={{flexDirection:'row',justifyContent:'space-between',gap:6,paddingHorizontal:Math.max(1,st?.padding??2),borderRadius:st?.radius??3}}><Text style={{color:prefs.secondaryTextColor,fontSize:Math.max(7,8*(st?.fontScale??100)/100),fontWeight:'700',flex:1}} numberOfLines={1}>{st?.fixed?'📌 ':''}{labels[k]??k}</Text><Text style={{color,fontSize:Math.max(7,9*(st?.fontScale??100)/100),fontWeight:st?.fontWeight??'bold',textAlign:st?.align??'right',flex:1}} numberOfLines={1}>{values[k]??'—'}</Text></View>})}</View></Animated.View></View>}
