 const insets=useSafeAreaInsets(); const [widgetDiag,setWidgetDiag]=useState<any>(null); const [safetyBackups,setSafetyBackups]=useState<SafetyBackup[]>([]); const [section,setSection]=useState<'theme'|'visibility'|'cards'|'focus'|'special'|'appicon'|'market'|'broker'|'widget'|'notify'|'ai'|'monitor'|'ota'|'data'>('theme'); const [settingsGroup,setSettingsGroup]=useState<string>('appearance'); const [page,setPage]=useState<PageFieldKey>('dashboard'); const [timeOpen,setTimeOpen]=useState(false); const [designerOpen,setDesignerOpen]=useState(false); const [immediateBusy,setImmediateBusy]=useState(false); const [themeDraftId,setThemeDraftId]=useState<ThemeId>(prefs.themeId); const [themeEdit,setThemeEdit]=useState<ThemeEditDraft>(()=>themeEditFromPrefs(prefs)); const [customThemeName,setCustomThemeName]=useState('我的佈景'); const ota=appSettings.ota,w=appSettings.widget,n=appSettings.closeNotification; const [layoutEditor,setLayoutEditor]=useState<{kind:'home';index:number}|{kind:'page';page:PageFieldKey}|{kind:'etf'}|null>(null); const [monitorFieldEdit,setMonitorFieldEdit]=useState<MonitorField|null>(null);
