 const saveCustomTheme=(slot:1|2|3|4|5)=>{const baseThemeId=(draftOfficial?.id??draftCustom?.baseThemeId??'obsidianGold');const saved={slot,name:(customThemeName.trim()||`我的佈景 ${slot}`),baseThemeId,tokens:{backgroundPreset:themeEdit.backgroundPreset,backgroundImageUri:themeEdit.backgroundImageUri,backgroundOpacity:themeEdit.backgroundOpacity,primaryTextColor:themeEdit.primaryTextColor,secondaryTextColor:themeEdit.secondaryTextColor,accentColor:themeEdit.accentColor,positiveColor:themeEdit.positiveColor,negativeColor:themeEdit.negativeColor,cardOpacity:themeEdit.cardOpacity,cardRadius:themeEdit.cardRadius,overlayOpacity:themeEdit.overlayOpacity,cardBackgroundImageUri:themeEdit.cardBackgroundImageUri,cardBackgroundImageOpacity:themeEdit.cardBackgroundImageOpacity,fontScale:themeEdit.fontScale,navMode:themeEdit.navDisplayMode,iconDisplay:{...themeEdit.iconDisplay}},savedAt:Date.now()};onChange({customThemes:[...prefs.customThemes.filter(x=>x.slot!==slot),saved].sort((a,b)=>a.slot-b.slot)});setThemeDraftId(`custom${slot}` as ThemeId);Alert.alert('自訂佈景已儲存',`${saved.name} 已存入自訂槽位 ${slot}；目前只儲存，尚未套用。按「確認套用」後才會變更全 App。`);};
