 const toggleWidget=(key:WidgetField)=>onWidgetChange({displayFields:w.displayFields.includes(key)?w.displayFields.filter(x=>x!==key):[...w.displayFields,key]}); const toggleNotify=(key:CloseNotificationField)=>onNotifyChange({displayFields:n.displayFields.includes(key)?n.displayFields.filter(x=>x!==key):[...n.displayFields,key]}); const toggleSymbol=(list:string[],sym:string,cb:(next:string[])=>void)=>cb(list.includes(sym)?list.filter(x=>x!==sym):[...list,sym]);
