 const saveLayout=(keys:string[],spans:Record<string,V3CardSpan>)=>{if(!layoutEditor)return;if(layoutEditor.kind==='home'){const cards=prefs.homeCardFields.map(x=>[...x]);const spanRows=prefs.homeCardSpans.map(x=>({...x}));while(cards.length<3)cards.push([]);while(spanRows.length<3)spanRows.push({});cards[layoutEditor.index]=keys as HomeMetricKey[];spanRows[layoutEditor.index]=spans;onChange({homeCardFields:cards,homeCardSpans:spanRows});return;}if(layoutEditor.kind==='page'){onChange({pageCardFields:{...prefs.pageCardFields,[layoutEditor.page]:keys},pageCardSpans:{...prefs.pageCardSpans,[layoutEditor.page]:spans}});return;}onChange({selectedEtfFields:keys,selectedEtfFieldSpans:spans});};
 const settingsGroups=[{key:'appearance',icon:'▣',label:'外觀版面',items:[['theme','主題'],['visibility','顯示控制'],['cards','全局卡片'],['focus','持倉焦點'],['special','特別設定'],['appicon','App ICON']]},{key:'monitor',icon:'◉',label:'監控工具',items:[['monitor','即時監控器'],['widget','桌面 Widget'],['market','市場數據']]},{key:'account',icon:'◎',label:'帳務券商',items:[['broker','券商']]},{key:'notice',icon:'✦',label:'通知 AI',items:[['notify','盤後訊息'],['ai','AI 助理']]},{key:'system',icon:'▤',label:'資料系統',items:[['ota','線上更新'],['data','資料']]}] as const;
