 {section==='visibility'?<><Card><SectionTitle title="全局資料顯示內鎖"/><Text style={s.note}>在這裡先過濾全 App 資訊。關閉只隱藏顯示，不刪除財務資料。</Text></Card><ToggleSetting label="底部 NAV 導覽列" value={prefs.visibility.nav} onChange={v=>onChange({visibility:{...prefs.visibility,nav:v}})}/><ToggleSetting label="NAV / 淨值資料" value={prefs.visibility.premium} onChange={v=>onChange({visibility:{...prefs.visibility,premium:v}})}/><ToggleSetting label="即時行情" value={prefs.visibility.liveQuote} onChange={v=>onChange({visibility:{...prefs.visibility,liveQuote:v}})}/><ToggleSetting label="今日損益" value={prefs.visibility.todayPnl} onChange={v=>onChange({visibility:{...prefs.visibility,todayPnl:v}})}/><ToggleSetting label="總損益" value={prefs.visibility.totalPnl} onChange={v=>onChange({visibility:{...prefs.visibility,totalPnl:v}})}/><ToggleSetting label="股息 / 配息資訊" value={prefs.visibility.dividends} onChange={v=>onChange({visibility:{...prefs.visibility,dividends:v}})}/><ToggleSetting label="市場新聞" value={prefs.visibility.marketNews} onChange={v=>onChange({visibility:{...prefs.visibility,marketNews:v}})}/><ToggleSetting label="AI 市場資訊" value={prefs.visibility.aiInsights} onChange={v=>onChange({visibility:{...prefs.visibility,aiInsights:v}})}/><ToggleSetting label="智慧跑馬燈" value={prefs.visibility.smartTicker} onChange={v=>onChange({visibility:{...prefs.visibility,smartTicker:v}})}/><ToggleSetting label="資料更新時間" value={prefs.visibility.updatedAt} onChange={v=>onChange({visibility:{...prefs.visibility,updatedAt:v}})}/></>:null}
