function DatePickerRow({label,value,show,onOpen,onClose,onChange}:{label:string;value:string;show:boolean;onOpen:()=>void;onClose:()=>void;onChange:(d:Date)=>void}){return <><TouchableOpacity style={s.field} onPress={onOpen}><Text style={s.fieldLabel}>{label}</Text><Text style={s.fieldValue}>{value}　📅</Text></TouchableOpacity>{show?<DateTimePicker value={parseDate(value)} mode="date" onChange={(_e:unknown,d?:Date)=>{onClose();if(d)onChange(d)}}/>:null}</>}
